<?php

declare(strict_types=1);

/**
 * lote22.php — Facturas al transportista.
 *
 * REQUIERE los lotes 12 a 21 aplicados.
 *
 * SIN MIGRACIÓN: las tablas `invoices`, `invoice_line_items` y
 * `financial_snapshots` ya estaban en el esquema desde el porte, y los
 * contadores de numeración también. Lo que faltaba era todo lo de encima.
 *
 * Qué instala:
 *   • `InvoiceController`: listado con totales de TODO el filtro, alta en dos
 *     pasos (transportista → cargas), ficha, envío, cobros y anulación.
 *   • `InvoiceBuilder`: convierte cargas entregadas en factura y, antes de
 *     escribir una sola línea, CONGELA el cálculo de cada carga en
 *     `financial_snapshots`. Es lo que hace defendible una factura: si mañana
 *     se le sube la tarifa al transportista o se aprueba un gasto, la factura
 *     emitida sigue diciendo lo que decía.
 *   • `InvoiceNumberGenerator`: contador por empresa con la fila bloqueada.
 *   • Tres pantallas y su diccionario EN/ES.
 *   • 12 pruebas Pest.
 *
 * TRES DECISIONES QUE NO SON DE ESTILO
 *
 *   • **Una factura emitida no se edita.** Se anula con motivo y se hace otra.
 *     Por eso no hay `edit` ni `update` en las rutas: no es un olvido.
 *   • **No hay columna «facturada» en `loads`.** Lo facturado se sabe
 *     preguntando por las líneas de facturas VIVAS. Una columna paralela se
 *     desincroniza en cuanto se anula una factura — y anular es justo cuando
 *     más falta hace acertar.
 *   • **No hay botón de «marcar como pagada».** Se anota el importe COBRADO y
 *     el saldo se recalcula. Un botón sin importe deja facturas cuadradas en la
 *     pantalla y descuadradas en el banco.
 *
 * El rol transportista tiene `invoice:read` con alcance Carrier, y aquí eso es
 * un FILTRO, no un 403: que vea lo que se le cobra es exactamente lo que debe
 * pasar.
 *
 * Cómo se ejecuta, desde la raíz del repositorio:
 *
 *     php lote22.php            # aplica
 *     php lote22.php --dry-run  # dice qué haría y no toca nada
 */

$raiz = __DIR__;
$dry = in_array('--dry-run', $argv, true);
$hechos = []; $saltados = []; $errores = [];

function ruta(string $rel): string { global $raiz; return $raiz.DIRECTORY_SEPARATOR.$rel; }

function nuevo(string $rel, string $contenido): void
{
    global $dry, $hechos, $saltados, $errores;
    $destino = ruta($rel);
    if (is_file($destino) && file_get_contents($destino) === $contenido) { $saltados[] = "= {$rel}"; return; }
    $existia = is_file($destino);
    if ($dry) { $hechos[] = ($existia ? '~ ' : '+ ').$rel; return; }
    $dir = dirname($destino);
    if (! is_dir($dir) && ! mkdir($dir, 0775, true) && ! is_dir($dir)) { $errores[] = "no se pudo crear el directorio {$dir}"; return; }
    if (file_put_contents($destino, $contenido) === false) { $errores[] = "no se pudo escribir {$rel}"; return; }
    $hechos[] = ($existia ? '~ ' : '+ ').$rel;
}

/**
 * Aplica trozos anclados. Si el resultado ya está, se salta; si el texto de
 * partida está una sola vez, se sustituye; si no, se aborta el fichero entero
 * sin escribir — un anclaje que no encaja significa que el fichero no es el que
 * este guion vio, y adivinar ahí es peor que parar.
 *
 * @param  list<array{0: string, 1: string}>  $pares
 */
function editar(string $rel, array $pares): void
{
    global $dry, $hechos, $saltados, $errores;
    $destino = ruta($rel);
    if (! is_file($destino)) { $errores[] = "falta {$rel} — ¿está en la raíz del repositorio?"; return; }
    $texto = file_get_contents($destino); $aplicados = 0; $yaEstaban = 0;
    foreach ($pares as $i => [$antes, $despues]) {
        if (str_contains($texto, $despues)) { $yaEstaban++; continue; }
        $veces = substr_count($texto, $antes);
        if ($veces !== 1) { $errores[] = "{$rel}: el trozo #".($i + 1)." no encaja ({$veces} coincidencias). No se tocó el fichero."; return; }
        $texto = str_replace($antes, $despues, $texto); $aplicados++;
    }
    if ($aplicados === 0) { $saltados[] = "= {$rel} ({$yaEstaban} trozo(s) ya estaban)"; return; }
    if ($dry) { $hechos[] = "~ {$rel} ({$aplicados} trozo(s))"; return; }
    if (file_put_contents($destino, $texto) === false) { $errores[] = "no se pudo escribir {$rel}"; return; }
    $hechos[] = "~ {$rel} ({$aplicados} trozo(s))";
}

foreach (['artisan', 'composer.json', 'app/Support/Navigation.php'] as $centinela) {
    if (! is_file(ruta($centinela))) {
        fwrite(STDERR, "Esto no parece la raíz del repositorio: falta {$centinela}.\n");
        exit(1);
    }
}

/* ── Ficheros nuevos ─────────────────────────────────────────────────── */

nuevo(
    "app/Support/Finance/InvoiceNumberGenerator.php",
    base64_decode(''),
);

nuevo(
    "app/Support/Finance/InvoiceBuilder.php",
    base64_decode(''),
);

nuevo(
    "app/Http/Controllers/App/InvoiceController.php",
    base64_decode(''),
);

nuevo(
    "lang/en/invoices.json",
    base64_decode(''),
);

nuevo(
    "lang/es/invoices.json",
    base64_decode(''),
);

nuevo(
    "resources/js/pages/App/Invoices/Index.tsx",
    base64_decode(''),
);

nuevo(
    "resources/js/pages/App/Invoices/Create.tsx",
    base64_decode(''),
);

nuevo(
    "resources/js/pages/App/Invoices/Show.tsx",
    base64_decode(''),
);

nuevo(
    "tests/Feature/Finance/InvoiceTest.php",
    base64_decode(''),
);


/* ── Ficheros que se modifican ───────────────────────────────────────── */

editar("routes/auth.php", [
    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('')],
]);

editar("app/Support/Navigation.php", [
    [base64_decode(''), base64_decode('')],
]);

/* ── Parte ───────────────────────────────────────────────────────────────── */

echo $dry ? "SIMULACIÓN (no se escribió nada)\n\n" : "lote22 — facturas al transportista\n\n";
foreach ($hechos as $l) { echo "  {$l}\n"; }
if ($saltados !== []) { echo "\n  ya estaba:\n"; foreach ($saltados as $l) { echo "    {$l}\n"; } }
if ($errores !== []) {
    echo "\nERRORES:\n";
    foreach ($errores as $l) { echo "  ! {$l}\n"; }
    echo "\nNada de lo que falló se escribió a medias.\n";
    exit(1);
}
if (! $dry) { echo <<<'TXT'

Siguiente paso, en este orden:

  npm run build
  ./vendor/bin/pest

No hay migración en este lote.

TXT; }
exit(0);
